def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip().lower()
        angle_match = re.search(r"<([^<>]*)>", value)
        if angle_match:
            value = angle_match.group(1).strip()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if not local or "." not in domain:
            return ""
        if domain.startswith(".") or domain.endswith("."):
            return ""
        return value

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value.strip(), fmt)
            except ValueError:
                pass
        raise ValueError("Invalid updated value: {!r}".format(value))

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        # Drop rows without either a valid email or a valid phone.
        if not email and not phone:
            continue

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row["tags"])
            if tag.strip()
        }

        normalized.append({
            "input_index": input_index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "tags": tags,
            "opted_out": is_opted_out(row["opted_out"]),
            "updated": parse_updated(row["updated"]),
            "source": row["source"].strip().lower(),
        })

    # Disjoint-set union for transitive matching.
    parent = list(range(len(normalized)))
    rank = [0] * len(normalized)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return
        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a
        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1

    by_email = {}
    by_phone_and_last_name = {}

    for i, row in enumerate(normalized):
        if row["email"]:
            previous = by_email.get(row["email"])
            if previous is None:
                by_email[row["email"]] = i
            else:
                union(i, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = by_phone_and_last_name.get(key)
            if previous is None:
                by_phone_and_last_name[key] = i
            else:
                union(i, previous)

    groups = {}
    for i, row in enumerate(normalized):
        groups.setdefault(find(i), []).append(row)

    def pick_field(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""
        chosen = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated"],
                -row["input_index"],
            ),
        )
        return chosen[field]

    output = []
    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["input_index"] for row in group),
    )

    for group in ordered_groups:
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated"] for row in group)

        output.append({
            "first_name": pick_field(group, "first_name"),
            "last_name": pick_field(group, "last_name"),
            "zip": pick_field(group, "zip"),
            "email": pick_field(group, "email"),
            "phone": pick_field(group, "phone"),
            "source": pick_field(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return output
